<?php
require_once "../config/koneksi.php"; require_once "../config/auth.php"; require_role("admin");
if($_SERVER["REQUEST_METHOD"]==="POST"){ $p=$_POST["pertanyaan"]; $a=$_POST["a"]; $b=$_POST["b"]; $c=$_POST["c"]; $d=$_POST["d"]; $j=$_POST["jawaban"]; $s=$conn->prepare("INSERT INTO soal (pertanyaan,pilihan_a,pilihan_b,pilihan_c,pilihan_d,jawaban) VALUES (?,?,?,?,?,?)"); $s->bind_param("ssssss",$p,$a,$b,$c,$d,$j); $s->execute(); header("Location: soal.php"); exit; }
if(isset($_GET["hapus"])){ $id=(int)$_GET["hapus"]; $s=$conn->prepare("DELETE FROM soal WHERE id=?"); $s->bind_param("i",$id); $s->execute(); header("Location: soal.php"); exit; }
$data=$conn->query("SELECT * FROM soal ORDER BY id DESC");
?>
